CREATE TABLE IF NOT EXISTS student(student_id VARCHAR(30) PRIMARY KEY, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(160) UNIQUE, program VARCHAR(120), status VARCHAR(30) NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS teacher(teacher_id VARCHAR(30) PRIMARY KEY, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(160) UNIQUE, department VARCHAR(120), status VARCHAR(30) NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS subject(subject_id VARCHAR(30) PRIMARY KEY, subject_code VARCHAR(30) UNIQUE NOT NULL, subject_name VARCHAR(160) NOT NULL, description TEXT, units INTEGER NOT NULL DEFAULT 3 CHECK(units>0));
CREATE TABLE IF NOT EXISTS class_offering(offering_id VARCHAR(30) PRIMARY KEY, class_code VARCHAR(40) NOT NULL, schedule VARCHAR(120), section VARCHAR(40), school_year VARCHAR(20), semester VARCHAR(30), room VARCHAR(60), subject_id VARCHAR(30) NOT NULL REFERENCES subject(subject_id), teacher_id VARCHAR(30) NOT NULL REFERENCES teacher(teacher_id));
CREATE TABLE IF NOT EXISTS enrollment(enrollment_id VARCHAR(30) PRIMARY KEY, student_id VARCHAR(30) NOT NULL REFERENCES student(student_id), offering_id VARCHAR(30) NOT NULL REFERENCES class_offering(offering_id), enroll_date DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(30) NOT NULL DEFAULT 'Enrolled', UNIQUE(student_id,offering_id));
CREATE TABLE IF NOT EXISTS grading_period(period_id VARCHAR(30) PRIMARY KEY, name VARCHAR(80) NOT NULL, start_date DATE, end_date DATE, school_year VARCHAR(20), semester VARCHAR(30), CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date));
CREATE TABLE IF NOT EXISTS grade_component(component_id VARCHAR(30) PRIMARY KEY, name VARCHAR(100) NOT NULL, type VARCHAR(50) NOT NULL, max_score NUMERIC(8,2) NOT NULL CHECK(max_score>0), description TEXT);
CREATE TABLE IF NOT EXISTS grade_percentage(percentage_id VARCHAR(30) PRIMARY KEY, component_id VARCHAR(30) NOT NULL REFERENCES grade_component(component_id) ON DELETE CASCADE, period_id VARCHAR(30) NOT NULL REFERENCES grading_period(period_id) ON DELETE CASCADE, percentage NUMERIC(5,2) NOT NULL CHECK(percentage BETWEEN 0 AND 100), UNIQUE(component_id,period_id));
CREATE TABLE IF NOT EXISTS grade_component_score(score_id VARCHAR(30) PRIMARY KEY, enrollment_id VARCHAR(30) NOT NULL REFERENCES enrollment(enrollment_id) ON DELETE CASCADE, component_id VARCHAR(30) NOT NULL REFERENCES grade_component(component_id), period_id VARCHAR(30) NOT NULL REFERENCES grading_period(period_id), score NUMERIC(8,2) NOT NULL CHECK(score>=0), remarks TEXT, date_recorded TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(enrollment_id,component_id,period_id));
CREATE TABLE IF NOT EXISTS grade(grade_id VARCHAR(30) PRIMARY KEY, enrollment_id VARCHAR(30) NOT NULL REFERENCES enrollment(enrollment_id) ON DELETE CASCADE, period_id VARCHAR(30) NOT NULL REFERENCES grading_period(period_id), final_grade NUMERIC(5,2), remarks VARCHAR(120), date_encoded TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(enrollment_id,period_id));
CREATE INDEX IF NOT EXISTS idx_student_name ON student(last_name,first_name);
CREATE INDEX IF NOT EXISTS idx_enrollment_student ON enrollment(student_id);
CREATE INDEX IF NOT EXISTS idx_grade_enrollment ON grade(enrollment_id);
